func (d *Downloader) Patch(id string, req *base.Request, opts *base.Options) error {
	task := d.GetTask(id)
	if task == nil {
		return ErrTaskNotFound
	}
	if err := func() error {
		task.lock.Lock()
		defer task.lock.Unlock()

		// Restore fetcher if not loaded
		if task.fetcher == nil {
			err := func() error {
				task.statusLock.Lock()
